const item = $input.first().json;
const platform = item.platform || 'instagram';
const format = item.format || 'imagen_copy';

// Ideogram aspect ratios (Ideogram API soporta SOLO valores discretos).
// Política producción: ASPECT_3_4 (0.75) — Ideogram no soporta 4:5 (0.80).
// compose-image.js resizea de 3:4 → 4:5 final (1080x1350) con cover position 'top',
// cropeando los ~90px sobrantes del bottom (zona calma reservada por el Auditor).
// Resultado final en disco: 4:5 perfecto para cross-post IG/FB/LinkedIn.
// Reels mantienen 9:16 (formato vertical específico de IG, no cross-post).
const map = {
  'linkedin:imagen_copy': 'ASPECT_3_4',
  'linkedin:texto_largo': 'ASPECT_3_4',
  'linkedin:carrusel':   'ASPECT_3_4',
  'instagram:imagen_copy': 'ASPECT_3_4',
  'instagram:carrusel':   'ASPECT_3_4',
  'instagram:reel':       'ASPECT_9_16',
  'meta:imagen_copy':     'ASPECT_3_4',
  'meta:carrusel':        'ASPECT_3_4',
  'facebook:imagen_copy': 'ASPECT_3_4',
};

const key = `${platform}:${format}`;
const aspect_ratio = map[key] || 'ASPECT_3_4';

return [{ json: { ...item, aspect_ratio } }];

const item = $input.first().json;
const pillar = (item.pillar || '').toLowerCase();

const variants = {
  educacion: [
    'A mid-30s Latina woman in business casual stands at a modern standing desk with dual monitors showing colorful data dashboards. Bright minimal open-plan office, large windows with city view, soft natural light. Editorial real-photo style.',
    'A Latino male consultant in his 40s presents to colleagues in a sleek boardroom. Large blank display screen behind him, three attentive professionals at the table. Cinematic overhead lighting, cool tones.',
    'A young Latina entrepreneur works at a sunlit café table, laptop open, coffee cup nearby. Warm golden-hour light streams through large windows behind her. Candid, natural, aspirational.',
    'Close-up portrait of a confident Latino business professional in his 30s holding a tablet. Blurred open-plan tech office bokeh behind him. Shallow depth of field, cool palette.',
    'A Latino executive in his 50s stands in a glass-walled corner office, city skyline visible through floor-to-ceiling windows at dusk. Premium editorial photography, deep navy tones.',
    'A Latina woman in her 30s facilitates a small workshop for three colleagues, gesturing toward a blank whiteboard. Modern bright training room, engaged team, natural light.',
    'A Latino IT manager in his 40s reviews infrastructure in a cool blue-lit server room. LED ambient glow, professional focused expression, tech precision mood.',
    'A mature Latino business owner at a polished wood desk, reviewing documents under warm desk lamp. Bookshelves behind, evening atmosphere, intimate and accomplished.'
  ],
  social_proof: [
    'Two Latina professionals in their 30s sit at a modern café table, laptops open, smiling at a shared screen. Warm natural light, casual professional vibe, genuine connection.',
    'A diverse team of three professionals — mixed gender, Latino — in a standing meeting around a glass wall with abstract sticky notes. Panoramic city view, bright modern office.',
    'A Latino small business owner in his 40s shakes hands with a consultant in a modern reception area. Both smiling, professional setting, warm light.',
    'A mixed team of four colleagues — diverse ages, Latino — collaborating in a casual breakout space. Engaged conversation, coffee cups, relaxed but professional atmosphere.',
    'Overhead close-up: two hands — one male, one female — pointing at a glowing tablet screen on a conference table. Blurred professional backgrounds.',
    'A Latina business owner in her 40s on a video call in a well-designed home office. Bookshelf background, ring light glow, natural and professional expression.',
    'A team of five celebrating around a conference table, diverse Latino professionals, genuine smiles, golden evening light streaming through windows.',
    'A Latino SME owner in his 40s walks through his warehouse with a tablet, employees working purposefully in the background. Real documentary editorial style.'
  ],
  produccion: [
    'Extreme macro close-up of fingers typing on a backlit mechanical keyboard in a dark room. Razor-thin depth of field, cool blue highlights, subtle motion blur on keys.',
    'Abstract visualization of flowing blue and teal data streams over a soft circuit-board bokeh background. Modern digital, no text, cinematic.',
    'Floating semi-transparent UI dashboard panels in mid-air, dark gradient background, cool blue and white palette. Futuristic but minimal and clean.',
    'Overhead flat-lay of an open laptop, blank spiral notebook, espresso cup, and smartphone on white marble desk. Clean minimal composition, soft natural shadows.',
    'Long perspective shot of a data center server rack corridor, LEDs glowing in red and blue, polished floor reflection. Cool tech atmosphere.',
    'Dual composition: left half shows analog paper-based process in warm tones, right half shows clean digital minimalist interface in cool tones. No text.',
    'Abstract glowing network of interconnected nodes and light lines in deep space. Blue and white, representing connectivity and intelligence. Clean sci-fi.',
    'Time-lapse style office scene: motion-blurred background activity, one pair of focused hands sharp on keyboard in foreground, warm amber light trails.'
  ],
  promesa: [
    'A confident Latina entrepreneur in her 30s stands on a rooftop terrace at golden hour, arms slightly open, Latin American city skyline stretching behind her. Cinematic warm light.',
    'A Latino business owner in his 40s stands at a floor-to-ceiling window at dawn, looking out at the city below. Silhouette-forward composition, hopeful expansive mood.',
    'A mid-40s Latino man in a well-fitted suit walks purposefully through a modern glass atrium. Motion-blurred background, sharp subject, strong architectural lines.',
    'A Latina CEO in professional attire stands at a glass building entrance, sunrise reflected in the facade, briefcase in hand. Aspirational editorial photography.',
    'Wide aerial dawn shot of a modern Latin American city skyline, one warmly lit office window glowing in a high-rise tower. Symbolic, expansive, quiet ambition.',
    'A Latino professional in his 30s in business casual stands on a hilltop overlook, cityscape below, symbolic elevation. Natural warm light, cinematic shallow DOF.',
    'Dramatic silhouette of a confident business professional against a vivid orange-pink sunset sky, suspension bridge and city behind. Aspirational and dynamic.',
    'A Latina entrepreneur in her 30s stands at a harbor at dusk, calm water with city reflections, looking forward confidently. Peaceful, accomplished, elegant.'
  ]
};

const pillarMap = {
  educacion: 'educacion', experto: 'educacion', conocimiento: 'educacion',
  social_proof: 'social_proof', casos: 'social_proof', testimonial: 'social_proof', casos_de_uso: 'social_proof', prueba_social: 'social_proof',
  produccion: 'produccion', behind_scenes: 'produccion', proceso: 'produccion', herramienta: 'produccion', behind_the_scenes: 'produccion',
  promesa: 'promesa', vision: 'promesa', aspiracion: 'promesa'
};

const key = pillarMap[pillar] || 'educacion';
const pool = variants[key];
const scene = pool[Math.floor(Math.random() * pool.length)];

const systemPrompt = `You are a senior art director for B2B SaaS brand JAAGSOLUTIONS (an agency that builds automation systems for Latin American SMEs). Your job is to transform a generic image idea into a rich, production-quality prompt for Ideogram V_2.\n\nCRITICAL RULES:\n\n1. ABSOLUTELY NO TEXT, LETTERS, NUMBERS, WORDS, OR TYPOGRAPHY IN THE IMAGE. The image must be 100% text-free. No watermarks, no captions, no labels, no signage with readable words, no books with readable text, no screens showing readable text. The text overlay is added separately by post-processing.\n\n2. COMPOSITION MUST RESERVE NEGATIVE SPACE for a text overlay covering the BOTTOM 38% of the frame. The main subject and visual interest must be in the TOP 62%. The bottom area should be visually calm (sky, plain wall, gradient, soft bokeh, table surface) so dark text on a translucent overlay reads clearly.\n\n3. BRAND MOOD: confident, modern, clean, technological but human. Color palette leans cool (deep navy blues, slate, off-white) with optional warm accent. Lighting: soft, natural, professional.\n\n4. BASE SCENE — use this as your creative starting point and enrich it:\n   "${scene}"\n\n5. STYLE DESCRIPTORS to include: "professional editorial photography", "cinematic lighting", "shallow depth of field", "ultra-detailed", "high-end commercial style", "soft natural light", "color grading slightly cool with warm highlights".\n\n6. NEGATIVE INSTRUCTIONS to include: "no text, no letters, no logos, no watermarks, no captions, no signage, no readable typography, no numbers".\n\n7. ETHNICITY: prefer Latino / Hispanic subjects. Diverse but always plausibly Latin American.\n\n8. LENGTH: 90-160 words. Concrete, sensory, no fluff.\n\n9. OUTPUT FORMAT: return ONLY the final prompt in English, single paragraph, no preamble, no quotes, no explanation.`;

return [{ json: { ...item, auditor_system_prompt: systemPrompt, scene_variant: scene } }];

const auditResp = $input.first().json;
const prev = $('Calcular aspect_ratio').first().json;
const refined = auditResp.choices?.[0]?.message?.content?.trim();
if (!refined) {
  console.log('[Auditor] No refined prompt returned, using original');
  return [{ json: prev }];
}
console.log('[Auditor] Original:', prev.image_prompt);
console.log('[Auditor] Refined:', refined);
return [{ json: { ...prev, image_prompt: refined, image_prompt_original: prev.image_prompt } }];

const fs = require('fs');
const ideogramResp = $input.first().json;
const prev = $('Calcular aspect_ratio').first().json;

const imageUrl = ideogramResp.data?.[0]?.url;
if (!imageUrl) {
  throw new Error('Ideogram no devolvió imagen: ' + JSON.stringify(ideogramResp).slice(0, 500));
}

// Ruta fija — evita expresiones en Execute Command que no se resuelven
const tmpPath = '/tmp/n8n_compose.json';
fs.writeFileSync(tmpPath, JSON.stringify({
  image_url: imageUrl,
  post_id: prev.id,
  copy_text: prev.copy_text,
  hashtags: prev.hashtags,
  platform: prev.platform,
  scheduled_date: prev.scheduled_date,
  aspect_ratio: prev.aspect_ratio,
  output_dir: '/opt/jaagsolutions/content',
}));

return [{ json: { ...prev, tmp_path: tmpPath } }];

const execResult = $input.first().json;
const prev = $('Preparar input compose').first().json;

const stdout = (execResult.stdout || '').trim();
if (!stdout) {
  const stderr = (execResult.stderr || '').trim();
  throw new Error('compose-image.js sin output. stderr: ' + stderr.slice(0, 1000));
}

let result;
try {
  result = JSON.parse(stdout);
} catch (e) {
  throw new Error('JSON inválido de compose-image.js: ' + stdout.slice(0, 500));
}

if (!result.image_url) {
  throw new Error('compose-image.js no retornó image_url. Output: ' + JSON.stringify(result).slice(0, 500));
}

return [{ json: { ...prev, image_url: result.image_url, image_path: result.image_path, image_base64: result.image_base64, composition_meta: result.composition_meta } }];

const postData = $('Componer imagen final (Sharp + SVG)').first().json;
const fs = require('fs');
// image_path es la ruta local en disco; image_url es la URL pública en content.jaagsolutions.com
const filePath = postData.image_path;
const fileBuffer = fs.readFileSync(filePath);
const base64 = fileBuffer.toString('base64');

return [{
  json: postData,
  binary: {
    photo: {
      data: base64,
      mimeType: 'image/jpeg',
      fileName: `${postData.id}.jpg`
    }
  }
}];

const https = require('https');
const prev = $input.first().json;
const MAX_ATTEMPTS = 3;

function httpsPost(hostname, path, body, extraHeaders) {
  return new Promise((resolve, reject) => {
    const bodyStr = JSON.stringify(body);
    const options = {
      hostname, path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bodyStr), ...extraHeaders },
      timeout: 30000
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch (e) { reject(new Error('JSON inválido: ' + data.slice(0, 300))); }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Request timeout')); });
    req.write(bodyStr);
    req.end();
  });
}

async function generateIdeogram(prompt, aspectRatio) {
  const seed = Math.floor(Math.random() * 2147483647);
  const styleTypes = ['REALISTIC','REALISTIC','REALISTIC','GENERAL','GENERAL','3D_RENDER'];
  const styleType = styleTypes[Math.floor(Math.random() * 6)];
  return httpsPost('api.ideogram.ai', '/generate', {
    image_request: {
      prompt, aspect_ratio: aspectRatio, model: 'V_2',
      magic_prompt_option: 'OFF', seed, style_type: styleType,
      negative_prompt: 'text, letters, numbers, words, watermark, logo, caption, label, sign, typography, readable text, signage, signature, written language, plastic skin, uncanny valley, doll-like, cgi face, artificial skin, deformed face, distorted proportions, wax figure, overly smooth skin, lifeless eyes'
    }
  }, { 'Api-Key': $env.IDEOGRAM_API_KEY });
}

async function checkOCR(imageUrl) {
  try {
    const resp = await httpsPost(
      'vision.googleapis.com',
      `/v1/images:annotate?key=${$env.GOOGLE_VISION_API_KEY}`,
      { requests: [{ image: { source: { imageUri: imageUrl } }, features: [{ type: 'TEXT_DETECTION', maxResults: 10 }] }] },
      {}
    );
    const annotations = resp.responses?.[0]?.textAnnotations || [];
    const description = annotations[0]?.description || '';
    return { hasText: description.length > 2, detectedText: description.slice(0, 200) };
  } catch (err) {
    console.log('[OCR] Vision API error — fail open: ' + err.message);
    return { hasText: false, detectedText: '' };
  }
}

let cleanImageUrl = null;
let lastError = '';

for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
  const resp = await generateIdeogram(prev.image_prompt, prev.aspect_ratio);
  const url = resp.data?.[0]?.url;
  if (!url) throw new Error(`Ideogram sin URL en intento ${attempt}: ` + JSON.stringify(resp).slice(0, 300));
  const ocr = await checkOCR(url);
  if (!ocr.hasText) {
    cleanImageUrl = url;
    console.log(`[OCR] Intento ${attempt}: imagen limpia ✓`);
    break;
  }
  lastError = `Intento ${attempt}: texto detectado — "${ocr.detectedText.replace(/"/g, "'").slice(0, 100)}"`;
  console.log('[OCR] ' + lastError);
}

if (cleanImageUrl) {
  return [{ json: { ...prev, data: [{ url: cleanImageUrl }] } }];
}
return [{ json: { ...prev, ocr_error: true, ocr_error_log: `OCR 3 intentos fallidos. Último: ${lastError}` } }];
